window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d2baa030eab1be2"]={"versions": [{"id": "FIG-9d2baa030eab1be2", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Modellierungsdiagramm zur Deliverable-Struktur eines Application Manifests in der Methodologie der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die hierarchische Einbettung von Prozess- und Ausführungsbeschreibungen in das Manifest-Deliverable mittels UML-artiger Aggregationen («nesting»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Hauptelemente:</p>\n<ul class=\"fig-list\"><li><strong>Application Manifest</strong>: Übergeordnetes Deliverable-Container-Element (dargestellt als Mappe/Briefumschlag-Symbol).\n</li><li><strong>Process</strong>: Dokumenten-Entität zur Beschreibung des Betriebssystem-Prozesses der Anwendung.\n</li><li><strong>Mode-dependent [startup configuration]</strong>: Dokumenten-Entität zur modal abhängigen Start- und Ausführungskonfiguration des Prozesses.\n</li></ul>\n<p class=\"fig-p\">Die Beziehungen zwischen dem übergeordneten Application Manifest und den beiden untergeordneten Spezifikationsdokumenten sind als Aggregationen mit dem Stereotyp <code>«nesting»</code> modelliert, jedoch ohne explizite Multiplizitätsangaben.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm; es stellt keinen sequenziellen Ablauf oder dynamisches Laufzeitverhalten dar, sondern die deklarative Strukturierung der Beschreibungsdateien für das Deployment eines Prozesses.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen ein Application Manifest so strukturieren, dass es die für das Deployment relevanten Prozessbeschreibungen sowie modenabhängige Startkonfigurationen umfasst. Da Multiplizitäten in dieser Fassung nicht explizit beziffert sind, ist für die formale Kardinalität auf das zugrundeliegende Adaptive-Metamodell zurückzugreifen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8238242e4100a738", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Modellierungsdiagramm zur Deliverable-Struktur eines Application Manifests in der Methodologie der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die hierarchische Einbettung von Prozess- und Ausführungsbeschreibungen in das Manifest-Deliverable mittels UML-artiger Aggregationen («nesting»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Hauptelemente:</p>\n<ul class=\"fig-list\"><li><strong>Application Manifest</strong>: Übergeordnetes Deliverable-Container-Element (dargestellt als Mappe/Briefumschlag-Symbol).\n</li><li><strong>Process</strong>: Dokumenten-Entität zur Beschreibung des Betriebssystem-Prozesses der Anwendung.\n</li><li><strong>Mode-dependent [startup configuration]</strong>: Dokumenten-Entität zur modal abhängigen Start- und Ausführungskonfiguration des Prozesses.\n</li></ul>\n<p class=\"fig-p\">Die Beziehungen zwischen dem übergeordneten Application Manifest und den beiden untergeordneten Spezifikationsdokumenten sind als Aggregationen mit dem Stereotyp <code>«nesting»</code> modelliert, jedoch ohne explizite Multiplizitätsangaben.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm; es stellt keinen sequenziellen Ablauf oder dynamisches Laufzeitverhalten dar, sondern die deklarative Strukturierung der Beschreibungsdateien für das Deployment eines Prozesses.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen ein Application Manifest so strukturieren, dass es die für das Deployment relevanten Prozessbeschreibungen sowie modenabhängige Startkonfigurationen umfasst. Da Multiplizitäten in dieser Fassung nicht explizit beziffert sind, ist für die formale Kardinalität auf das zugrundeliegende Adaptive-Metamodell zurückzugreifen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-022b4986fb5fc0e0", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Modellierungsdiagramm zur Deliverable-Struktur eines Application Manifests in der Methodologie der AUTOSAR Adaptive Platform. Das Diagramm visualisiert die hierarchische Einbettung von Prozess- und Ausführungsbeschreibungen in das Manifest-Deliverable mittels UML-artiger Aggregationen («nesting»).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt drei Hauptelemente:</p>\n<ul class=\"fig-list\"><li><strong>Application Manifest</strong>: Übergeordnetes Deliverable-Container-Element (dargestellt als Mappe/Briefumschlag-Symbol).\n</li><li><strong>Process</strong>: Dokumenten-Entität zur Beschreibung des Betriebssystem-Prozesses der Anwendung.\n</li><li><strong>Mode-dependent [startup configuration]</strong>: Dokumenten-Entität zur modal abhängigen Start- und Ausführungskonfiguration des Prozesses.\n</li></ul>\n<p class=\"fig-p\">Die Beziehungen zwischen dem übergeordneten Application Manifest und den untergeordneten Spezifikationsdokumenten sind als Aggregationen mit dem Stereotyp <code>«nesting»</code> ausgeführt:</p>\n<ul class=\"fig-list\"><li>Zum Dokument <strong>Process</strong> besteht eine feste Kardinalität von genau <code>1</code>.\n</li><li>Zum Dokument <strong>Mode-dependent...</strong> besteht eine Kardinalität von <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm; es stellt keinen sequenziellen Ablauf oder dynamisches Laufzeitverhalten dar, sondern die deklarative Strukturierung der Beschreibungsdateien für das Deployment eines Prozesses.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Generierungswerkzeuge müssen sicherstellen, dass jedes Application Manifest genau eine Prozessdefinition (<code>Process</code>, Multiplizität 1) enthält. Modenabhängige Startkonfigurationen (<code>Mode-dependent...</code>) sind optional und können mehrfach (<code>0..*</code>) im Deliverable eingebettet werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9d2baa030eab1be2", "to": "FIG-8238242e4100a738", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8238242e4100a738", "to": "FIG-022b4986fb5fc0e0", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Multiplizität <code>1</code> an der Assoziationskante <code>«nesting»</code> zu <code>Process</code>.\n</li><li>Ergänzung der Multiplizität <code>0..*</code> an der Assoziationskante <code>«nesting»</code> zu <code>Mode-dependent...</code> (Mode-dependent startup configuration).\n</li></ul>"}]};
